<?php

/*
 * Truncated JPEGs against sharp (re-review N1): tests/Fixtures/jpeg holds three JPEGs (baseline and progressive written
 * by sharp, the tests/api portrait) and verdicts.json — Express's raster pipeline (sharp failOn 'error') on cuts of
 * each, from a missing EOI to half the file, generated by tests/Fixtures/jpeg/generate.mjs. sharp's verdict with one
 * libvips thread is deterministic: every truncation is refused. At sharp's default concurrency a baseline JPEG cut near
 * its end is accepted only some of the time (a race inside libvips, `acceptedOf20`), so the deterministic verdict is
 * the one the port follows.
 */

use App\Http\Problem\Problem;
use App\Infrastructure\Images\Images;
use Tests\TestCase;

uses(TestCase::class);

function jpegVerdicts(): array
{
    return json_decode((string) file_get_contents(__DIR__.'/../../Fixtures/jpeg/verdicts.json'), true);
}

it('answers a truncated JPEG as sharp with one thread does', function (string $case) {
    $v = jpegVerdicts()[$case];
    $bytes = substr((string) file_get_contents(__DIR__.'/../../Fixtures/jpeg/'.explode(':', $case)[0].'.jpg'), 0, $v['length']);
    try {
        Images::variants($bytes, 'image/jpeg');
        $accepted = true;
    } catch (Problem $p) {
        expect($p->status)->toBe(415);
        $accepted = false;
    }
    expect($accepted)->toBe($v['accepted']);
})->with(array_keys(jpegVerdicts()));

it('sharp accepts whole files and refuses half or progressive truncations at any concurrency', function () {
    // Whole files are always accepted, a half or a progressive truncation is always refused, at any concurrency.
    foreach (jpegVerdicts() as $case => $v) {
        if (str_ends_with($case, ':full')) {
            expect($v['acceptedOf20'])->toBe(20);
        } elseif (str_ends_with($case, ':half') || str_starts_with($case, 'progressive:')) {
            expect($v['acceptedOf20'])->toBe(0);
        }
    }
});
